class Solution {
    public String largestMerge(String word1,String word2){
        StringBuilder answer=new StringBuilder();
        int first=0,second=0;
        while(first<word1.length()&&second<word2.length())if(word1.substring(first).compareTo(word2.substring(second))>0)answer.append(word1.charAt(first++));
        else answer.append(word2.charAt(second++));
        return answer.append(word1.substring(first)).append(word2.substring(second)).toString();
    }
}

code.kotlin:
class Solution {
    fun largestMerge(word1:String,word2:String):String{
        val answer=StringBuilder();
        var first=0;
        var second=0;
        while(first<word1.length&&second<word2.length)if(word1.substring(first)>word2.substring(second))answer.append(word1[first++]) else answer.append(word2[second++]);
        answer.append(word1.substring(first));
        answer.append(word2.substring(second));
        return answer.toString()
    }
}

code.cpp:
class Solution {
    public: string largestMerge(string word1,string word2){
        string answer;
        int first=0,second=0;
        while(first<(int)word1.size()&&second<(int)word2.size())if(word1.compare(first,string::npos,word2,second,string::npos)>0)answer+=word1[first++];
        else answer+=word2[second++];
        return answer+word1.substr(first)+word2.substr(second);
    }
};
